  // ---------- квартал ----------
  emQuarter(rep) {
    const E = Game.em();
    // войны
    for (const [k, L] of Object.entries(E.st)) {
      if (L.s === 'war') {
        const d = (Game.emPower(k) - Game.emFoe(k)) * 0.4 + (Math.random() * 20 - 10) * (1 + E.stance * 0.25);
        L.front = clamp(L.front + d, -100, 100);
        S.army = clamp(S.army - (1 + E.stance * 0.6) - (L.front < -30 ? 0.6 : 0));
        S.economy = clamp(S.economy - 0.3);
        if (S.turn - L.since >= 5) { S.support = clamp(S.support - 0.6); S.fac.left.a = clamp(S.fac.left.a - 0.6); }
        if (L.front >= 95) rep.lines.push(`${COUNTRIES[k].name} разбит и ждёт ваших условий. Предложите мир, пока там не передумали сдаваться.`);
        else if (L.front <= -50 && L.front > -80) rep.warn.push(`Война идёт плохо: ${LANDS[k].short} теснит легионы. Маршал называет это «сокращением фронта».`);
      } else if (L.s === 'ally') {
        const kin = E.pick === k || (E.wife && E.wife.k === k);
        S.rel[k] = clamp((S.rel[k] || 0) + (kin ? 0.6 : -0.4)); S.economy = clamp(S.economy + 0.15);
        if (!kin && (S.rel[k] || 0) < 40) { L.s = 'peace'; E.glory = clamp(E.glory - 4); rep.warn.push(`${COUNTRIES[k].name} выходит из союза: «в связи с изменившимися обстоятельствами». Обстоятельства — это вы.`); }
      } else if (L.s === 'vassal') {
        S.rel[k] = clamp((S.rel[k] || 0) - 0.8);
        if ((S.army < 50 || E.glory < 35 || (S.rel[k] || 0) < 15) && Math.random() < 0.14) { L.s = 'war'; L.front = -10; L.since = S.turn; L.cb = true; E.glory = clamp(E.glory - 4); rep.warn.push(`Вассал восстал: ${COUNTRIES[k].name} больше не платит дань и собирает войско.`); }
      } else if (S.turn >= L.truce && S.turn >= 4 && E.pick !== k && (S.rel[k] || 0) < 22 && Math.random() < (k === 'orcs' ? 0.26 : 0.16) * (S.army >= 75 ? 0.5 : 1)) {
        L.s = 'war'; L.front = -8; L.since = S.turn; L.cb = true;
        const B = E.br[k]; if (B && E.phase !== 'wed') B.gone = true;
        rep.warn.push(k === 'orcs' ? 'Орда перешла границу. Объявления войны не было: у Орды для этого нет слова.' : `${COUNTRIES[k].name} объявляет империи войну. Нота вручена по всей форме, на гербовой бумаге.`);
      }
    }
    if (E.st.orcs.s === 'peace') S.rel.orcs = clamp((S.rel.orcs || 0) - 0.5);
    // величие: великой империи положено побеждать
    if (E.glory > 35) E.glory = clamp(E.glory - (E.glory > 80 ? 1.8 : E.glory > 60 ? 1.1 : 0.6));
    if (E.glory >= 70) { S.support = clamp(S.support + 0.4); S.fac.oligarchs.a = clamp(S.fac.oligarchs.a + 0.4); }
    if (E.glory < 30) { S.fac.oligarchs.a = clamp(S.fac.oligarchs.a - 1); S.fac.hawks.a = clamp(S.fac.hawks.a - 1); if (S.turn % 4 === 0) rep.warn.push('Величие империи померкло. Высокие дома вспоминают, что императоров бывает больше одного.'); }
    // невесты
    if (E.phase === 'court') {
      const here = Object.keys(E.br).filter(k => !E.br[k].gone);
      for (const k of here) { const B = E.br[k]; B.favor = clamp(B.favor - 1); if (B.favor < 10) { B.gone = true; S.rel[k] = clamp((S.rel[k] || 0) - 5); rep.lines.push(`${BRIDES[k].short} уехала, не дождавшись внимания. Её посол откланялся подчёркнуто вежливо.`); } }
      const base = E.recalled || 0;
      if (S.turn - base >= 12 && S.turn % 2 === 0) { const left = Object.keys(E.br).filter(k => !E.br[k].gone).sort((a, b) => E.br[a].favor - E.br[b].favor)[0]; if (left) { E.br[left].gone = true; S.rel[left] = clamp((S.rel[left] || 0) - 4); rep.lines.push(`${BRIDES[left].short} устала ждать и вернулась домой. Смотрины затянулись.`); } }
      if (!Object.keys(E.br).some(k => !E.br[k].gone)) { E.phase = 'single'; rep.warn.push('Все невесты разъехались. Двор в ужасе, вдовствующая императрица в ярости. Портреты можно разослать заново.'); }
    }
    if ((E.phase === 'court' || E.phase === 'single') && S.turn >= 8) { S.fac.oligarchs.a = clamp(S.fac.oligarchs.a - 0.7); S.fac.faith.a = clamp(S.fac.faith.a - 0.5); if (S.turn % 4 === 0) rep.warn.push('Империи нужен наследник, а у императора нет даже невесты. Высокие дома начали присматривать замену. Трону, не невесте.'); }
    const W = E.wife;
    if (W) {
      if (W.away) S.rel[W.k] = clamp((S.rel[W.k] || 0) - 2);
      else {
        W.mood = clamp(W.mood + (W.mood > 52 ? -1 : W.mood < 48 ? 1 : 0) - (Game.emCount('war') && E.stance === 2 ? 1 : 0));
        const m = Game.emBonusMult(), b = BRIDES[W.k].bonus;
        if (m) { for (const st of ['support', 'economy', 'army', 'fear']) if (b[st]) S[st] = clamp(S[st] + b[st] * m); for (const [f, d] of Object.entries(b.fac || {})) if (S.fac[f]) S.fac[f].a = clamp(S.fac[f].a + d.a * m); }
        if (W.mood < 20) { W.away = true; S.rel[W.k] = clamp((S.rel[W.k] || 0) - 10); rep.warn.push(`Императрица уехала к родне. ${BRIDES[W.k].short} сказала, что вернётся, «когда во дворце станет с кем разговаривать».`); }
      }
    }
  },
